create table if not exists public.inventory_transaction_reversals(original_transaction_id uuid primary key references public.inventory_transactions(id),reversal_transaction_id uuid not null unique references public.inventory_transactions(id),reason text not null,reversed_by uuid not null references auth.users(id),reversed_at timestamptz not null default now());alter table public.inventory_transaction_reversals enable row level security;create policy inventory_reversals_read on public.inventory_transaction_reversals for select to authenticated using(true);grant select on public.inventory_transaction_reversals to authenticated;
create or replace function public.reverse_inventory_transaction(p_transaction_id uuid,p_reason text,p_idempotency_key uuid) returns public.inventory_transactions language plpgsql security definer set search_path=public as $$ declare v_original public.inventory_transactions%rowtype;v_reverse public.inventory_transactions%rowtype;v_type text;begin if auth.uid() is null then raise exception 'Authentication required';end if;if public.current_user_role() not in ('admin','site_manager') then raise exception 'Only admin/site manager can reverse a posted stock movement';end if;if coalesce(trim(p_reason),'')='' then raise exception 'Correction reason is required';end if;select * into v_original from public.inventory_transactions where id=p_transaction_id for update;if not found then raise exception 'Original transaction not found';end if;if exists(select 1 from public.inventory_transaction_reversals where original_transaction_id=p_transaction_id) then raise exception 'Transaction has already been reversed';end if;v_type:=case v_original.transaction_type when 'MASUK' then 'PENYESUAIAN_KELUAR' when 'KELUAR' then 'PENYESUAIAN_MASUK' when 'PENYESUAIAN_MASUK' then 'PENYESUAIAN_KELUAR' else 'PENYESUAIAN_MASUK' end;select * into v_reverse from public.record_inventory_mutation_v2(p_idempotency_key,v_original.item_id,v_type,v_original.quantity,now(),'REV-'||coalesce(v_original.reference_no,v_original.id::text),'Koreksi transaksi',v_original.location,p_reason,coalesce(v_original.destination_name,'Lokasi proyek'),coalesce(v_original.source_name,'Lokasi asal'),'Koreksi oleh pengguna',v_original.owner_type,'Pembalikan transaksi '||v_original.id,v_original.addition_id);insert into public.inventory_transaction_reversals(original_transaction_id,reversal_transaction_id,reason,reversed_by) values(v_original.id,v_reverse.id,p_reason,auth.uid());insert into public.audit_logs(actor_id,action,entity_type,entity_id,details) values(auth.uid(),'INVENTORY_REVERSAL','inventory_transaction',v_original.id::text,jsonb_build_object('actor_name',(select full_name from public.profiles where id=auth.uid()),'original_transaction_id',v_original.id,'reversal_transaction_id',v_reverse.id,'reason',p_reason));return v_reverse;end $$;revoke all on function public.reverse_inventory_transaction(uuid,text,uuid) from public,anon;grant execute on function public.reverse_inventory_transaction(uuid,text,uuid) to authenticated;